import { join } from "path";

export interface AppConfig {
  /** 고객 알림 토픽 */
  topic: string;
  /** 사내 메시지 키 네임스페이스 */
  keyNamespace: string;
  /** mqpub 실행 파일 경로 */
  mqpubBin: string;
  /** mqpub 스풀 디렉토리(MQPUB_SPOOL) */
  spoolDir: string;
  /** 문자 발신 번호 */
  senderId: string;
  /** 한 번에 읽어 올 최대 메시지 수 */
  drainLimit: number;
}

