 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub은 한 배치 안에서 키 끝부분이 같은 메시지를 중복으로 보고 첫 것만 저장한다(오류 없음).
 * 업무 식별자(일련번호)는 키 끝에 놓이므로 서로 다른 주문이 같은 키 끝을 갖게 된다.
 * 그래서 논리 키의 결정적 해시를 맨 끝에 붙인다 — 메시지마다 끝이 달라지고,
 * 같은 알림은 늘 같은 키라 소비 측 중복 방지는 그대로 동작한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  return `${logical}:${createHash("sha1").update(logical).digest("hex").slice(0, 12)}`;
}

